CREATE TABLE CORE.T_FACT_CUSTOMER_GOODWILL_LINE_2 (
   CUST_ORDER_GOODWILL_SID             NUMERIC         NOT NULL COMMENT 'The unique identifier (surrogate key) for the goodwill of customer order
            The unique identifier (surrogate key) for the goodwill of customer order',
   CUST_ORDER_GOODWILL_POS_NR          NUMERIC(38,0)   NOT NULL COMMENT 'A number of an particular position (product) in the goodwill order',
   WSHOP_CD                            VARCHAR(5)      COMMENT 'The unique code for the Lidl webshop',
   CUST_ORDER_SID                      NUMERIC         COMMENT 'The unique identifier (surrogate key) for customer order',
   CUST_ORDER_POS_NR                   NUMERIC(38,0)   COMMENT 'The particular position number of an item_2 in an order',
   PROD_VARIANT_SID                    NUMERIC         COMMENT 'A product in the goodwill',
   PROD_SID                            NUMERIC         COMMENT 'The unique identifier (surrogate key) for the product',
   CUST_SID                            NUMERIC         COMMENT 'The unique identifier (surrogate key) for the customer',
   CURR_CD                             VARCHAR(5)      COMMENT 'The code identifying the currency according to ISO-4217.',
   CUST_ORDER_TYPE_CD                  VARCHAR(5)      COMMENT 'This field contains codes for two credit notes: ZCGW for price reduction/compensation (for goodwill credit note) and ZCMR for item_2 refund (value credit note)',
   CUST_PAYM_METHOD_CD                 VARCHAR(5)      COMMENT 'Unique code of the payment method',
   DELIVERY_ADDR_SID                   NUMERIC         COMMENT 'The unique identifier (sk) for the delivery address_2 where original order was delivered',
   BILLING_ADDR_SID                    NUMERIC         COMMENT 'The unique identifier (sk) for the billing address_2',
   GOODWILL_REASON_CD                  VARCHAR(5)      COMMENT 'The code for the goodwill reason.',
   CUST_ORDER_GOODWILL_NR              VARCHAR(20)     COMMENT 'An original goodwill order number',
   CUST_ORDER_NR                       VARCHAR(20)     COMMENT 'The original order number of the source system',
   CUST_ORDER_GOODWILL_CREATE_TMSP     TIMESTAMP_TZ(9) COMMENT 'Creation timestamp of the goodwill.',
   CUST_ORDER_CREATE_TMSP              TIMESTAMP_TZ(9) COMMENT 'The timestamp when order was created in source system ( is used in reporting)',
   PROD_VARIANT_NR                     VARCHAR(20)     COMMENT 'The product variant number',
   PROD_NR                             VARCHAR(20)     COMMENT 'The number for internal onlineshop product, which is country_2 independent',
   CUST_ORDER_DT                       DATE            COMMENT 'The date when order was made',
   CUST_ORDER_GOODWILL_DT              DATE            COMMENT 'The date when goodwill was made',
   PROD_QTY                            NUMERIC(38,5)   COMMENT 'Quantity of a particular product in the goodwill',
   IS_GHOST_PACK_FG                    BOOLEAN         COMMENT 'Indicator if the package_2 was lost during the transfer process from the warehouse to the logistics company (carrier).',
   IS_PACK_LOST_BY_HAULER_FG           BOOLEAN         COMMENT 'Indicator if the package_2 was lost during the transfer process from the logistics company (hauler) to the customer.',
   PROD_PRICE_GOODWILL_NET_LOCAL_VAL   NUMERIC(38,5)   COMMENT 'Goodwill amount from the product price (net in local currency)',
   PROD_PRICE_GOODWILL_GROSS_LOCAL_VAL NUMERIC(38,5)   COMMENT 'Goodwill amount from the product price (gross in local currency)',
   PROD_PRICE_GOODWILL_VAT_LOCAL_VAL   NUMERIC(38,5)   COMMENT 'Goodwill amount from the VAT of the product price (local currency)',
   PROD_COUPON_GOODWILL_NET_LOCAL_VAL  NUMERIC(38,5)   COMMENT 'Goodwill amount from the discount coupon value (net in local currency)',
   PROD_COUPON_GOODWILL_GROSS_LOCAL_VAL NUMERIC(38,5)   COMMENT 'Goodwill amount from the discount coupon value  (gross in local currency)',
   PROD_COUPON_GOODWILL_VAT_LOCAL_VAL  NUMERIC(38,5)   COMMENT 'Goodwill amount from the VAT of the discount coupon value (local currency)',
   DELIVERY_COST_GOODWILL_NET_LOCAL_VAL NUMERIC(38,5)   COMMENT 'Goodwill amount from the delivery costs for the product (net in local currency). This cost is optional and mostly article dependent. An example is a fridge which has additional delivery costs.',
   DELIVERY_COST_GOODWILL_GROSS_LOCAL_VAL NUMERIC(38,5)   COMMENT 'Goodwill amount from the delivery costs for the product (gross in local currency). This cost is optional and mostly article dependent. An example is a fridge which has additional delivery costs.',
   DELIVERY_COST_GOODWILL_VAT_LOCAL_VAL NUMERIC(38,5)   COMMENT 'Goodwill amount from the delivery vat value for the product in local currency. This tax value is optional and mostly article dependent. An example is a fridge which has additional delivery costs for which taxes might have to be paid.',
   DELIVERY_PAUSHAL_GOODWILL_NET_LOCAL_VAL NUMERIC(38,5)   COMMENT 'Goodwill amount from the paushal for delivery costs specific to the product (net in local currency).',
   DELIVERY_PAUSHAL_GOODWILL_GROSS_LOCAL_VAL NUMERIC(38,5)   COMMENT 'Goodwill amount from the paushal for delivery costs specific to the product (gross in local currency).',
   DELIVERY_PAUSHAL_GOODWILL_VAT_LOCAL_VAL NUMERIC(38,5)   COMMENT 'Goodwill amount from the VAT value of the paushal delivery costs specific to the product (in local currency).',
   ADD_DELIVERY_PAUSHAL_GOODWILL_NET_LOCAL_VAL NUMERIC(38,5)   COMMENT 'Goodwill amount from the additional net delivery fee/paushal for special destinations (Distribution Zones),  splitted per every order position in local currency.',
   ADD_DELIVERY_PAUSHAL_GOODWILL_GROSS_LOCAL_VAL NUMERIC(38,5)   COMMENT 'Goodwill amount from the additional gross delivery fee/paushal for special destinations (Distribution Zones),  splitted per every order position in local currency',
   ADD_DELIVERY_PAUSHAL_GOODWILL_VAT_LOCAL_VAL NUMERIC(38,5)   COMMENT 'Goodwill amount from the additional vat on delivery fee/paushal for special destinations (Distribution Zones),  splitted per every order position in local currency',
   DELIVERY_PAUSHAL_COUPON_GOODWILL_NET_LOCAL_VAL NUMERIC(38,5)   COMMENT 'Goodwill amount from the discount value net for paushal delivery cost specific to the product (in local currency).',
   DELIVERY_PAUSHAL_COUPON_GOODWILL_GROSS_LOCAL_VAL NUMERIC(38,5)   COMMENT 'Goodwill amount from the discount value gross for paushal delivery cost specific to the product (in local currency).',
   DELIVERY_PAUSHAL_COUPON_GOODWILL_VAT_LOCAL_VAL NUMERIC(38,5)   COMMENT 'Goodwill amount from the discount vat value for paushal delivery cost specific to the product (in local currency).',
   ADD_SERVICES_VAT_LOCAL_VAL          NUMERIC(38,5)   COMMENT 'Goodwill vat amount for Additional services in local currency. This cost is optional and mostly article dependent.',
   ADD_SERVICES_GROSS_LOCAL_VAL        NUMERIC(38,5)   COMMENT 'Goodwill gross amount for Additional services in local currency. This cost is optional and mostly article dependent.',
   ADD_SERVICES_NET_LOCAL_VAL          NUMERIC(38,5)   COMMENT 'Goodwill net amount for Additional services in local currency. This cost is optional and mostly article dependent.',
   DROPSHIPMENT_ORDER_FG               BOOLEAN         COMMENT 'In case the material is being sent from the supplier_2 this field will be filled.',
   DIST_CHANNEL_CD                     VARCHAR(5)      COMMENT 'The code for the distribution channel ( a channel  through which the goods are sold )',
   DIST_CHANNEL_TYPE_CD                VARCHAR(5)      COMMENT 'A  type of distribution channel ( Wshop for LD Webshop , IC for Intercompany)',
   DIST_COUNTRY_CD                     VARCHAR(5)      COMMENT 'The unique code for a country_2 according to ISO-3166 Alpha-2. E.g. \"DE\" for Germany or \"FR\" for France',
   DIST_ZONE_CD                        VARCHAR(5)      COMMENT 'The unique code for a distribution zone ( f.e. BAL , CAN, etc)',
   DWH_CREATED_TMSP                    TIMESTAMP_LTZ(9) NOT NULL COMMENT 'The point in time when this record was created in the data warehouse.',
   DWH_UPDATED_TMSP                    TIMESTAMP_LTZ(9) NOT NULL COMMENT 'The point in time when this record was last updated.',
   DWH_SRC_FILE_NAME                   VARCHAR(255)    NOT NULL COMMENT 'The path and the name of the file(s) from which this record was loaded.',
   SRC_FILE_TMSP                       TIMESTAMP_LTZ(9) NOT NULL COMMENT 'The point in time when this record was extracted from the source.',   
   CONSTRAINT PK_T_FACT_CUSTOMER_GOODWILL_LINE PRIMARY KEY (CUST_ORDER_GOODWILL_SID, CUST_ORDER_GOODWILL_POS_NR) NOT ENFORCED 
)  COMMENT = 'The goodwill is a situation when a certain amount was returned to the customer from his paid order by an onlineshop without the customer having to return the good (e.g. damaged item_2). Table contain information about details of individual goodwill cases.';
